const now = new Date();
const until = now.toISOString();
const sinceDate = new Date(now);
sinceDate.setUTCDate(sinceDate.getUTCDate() - 7);
const since = sinceDate.toISOString();
const repo = $env.GITHUB_REPO || 'claude-builders-bounty/claude-builders-bounty';
const language = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();
const delivery = $env.DELIVERY_TARGET || 'discord';
return [{ json: { repo, language, delivery, since, until, sinceDate: since.slice(0, 10), untilDate: until.slice(0, 10) } }];

const window = $('Build Weekly Window').item.json;
const githubAccessToken = $env.GITHUB_TOKEN || '';
const headers = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
};
if (githubAccessToken) headers.Authorization = `Bearer ${githubAccessToken}`;
const getJson = async (url) => helpers.httpRequest({ method: 'GET', url, headers, json: true });
const repo = encodeURIComponent(window.repo).replace('%2F', '/');
const commitsUrl = `https://api.github.com/repos/${repo}/commits?since=${encodeURIComponent(window.since)}&until=${encodeURIComponent(window.until)}&per_page=100`;
const issuesUrl = `https://api.github.com/repos/${repo}/issues?state=closed&since=${encodeURIComponent(window.since)}&per_page=100`;
const mergedPrsUrl = `https://api.github.com/search/issues?q=${encodeURIComponent(`repo:${window.repo} is:pr is:merged merged:${window.sinceDate}..${window.untilDate}`)}&per_page=100`;
const [commits, issues, mergedPrSearch] = await Promise.all([
  getJson(commitsUrl),
  getJson(issuesUrl),
  getJson(mergedPrsUrl),
]);
const closedIssues = Array.isArray(issues) ? issues.filter((item) => !item.pull_request) : [];
const pullRequests = Array.isArray(mergedPrSearch.items) ? mergedPrSearch.items : [];
return [{ json: { ...window, commits: Array.isArray(commits) ? commits : [], closedIssues, pullRequests } }];

const window = $json;
const commits = Array.isArray(window.commits) ? window.commits : [];
const issues = Array.isArray(window.closedIssues) ? window.closedIssues : [];
const pullRequests = Array.isArray(window.pullRequests) ? window.pullRequests : [];
const compactCommits = commits.slice(0, 40).map((commit) => ({ sha: commit.sha?.slice(0, 7), message: commit.commit?.message?.split('
')[0], author: commit.commit?.author?.name }));
const compactIssues = issues.slice(0, 40).map((issue) => ({ number: issue.number, title: issue.title, closed_at: issue.closed_at }));
const compactPulls = pullRequests.slice(0, 40).map((pr) => ({ number: pr.number, title: pr.title, url: pr.html_url }));
const prompt = `Write a weekly narrative development summary in ${window.language}. Repository: ${window.repo}. Window: ${window.sinceDate} to ${window.untilDate}. Include a short intro, highlights, merged PRs, closed issues, commit themes, and next-week watch items. Keep it readable for product and engineering stakeholders.

Commits:
${JSON.stringify(compactCommits, null, 2)}

Closed issues:
${JSON.stringify(compactIssues, null, 2)}

Merged PRs:
${JSON.stringify(compactPulls, null, 2)}`;
return [{ json: { ...window, commitCount: commits.length, closedIssueCount: issues.length, mergedPrCount: pullRequests.length, prompt } }];

const window = $('Compose Claude Prompt').item.json;
const response = $json;
const text = response.content?.map((part) => part.text || '').join('
').trim() || 'Claude returned no text.';
const content = `# Weekly Dev Summary: ${window.repo}

${text}

---
Window: ${window.sinceDate} to ${window.untilDate}
Commits: ${window.commitCount} | Closed issues: ${window.closedIssueCount} | Merged PRs: ${window.mergedPrCount}`;
return [{ json: { ...window, summary: content, discordPayload: { content } } }];
